1	export type Cell = [number, number];
2	
3	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
4	
5	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
6	  const sameCell = x === otherX && y === otherY;
7	  return !sameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
8	}
9	
10	function countLiveNeighbors(cell: Cell, livingCells: Cell[]): number {
11	  return livingCells.filter((other) => isNeighbor(cell, other)).length;
12	}
13	
14	function survives(liveNeighbors: number): boolean {
15	  return SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors);
16	}
17	
18	export function nextGeneration(cells: Cell[]): Cell[] {
19	  return cells.filter((cell) => survives(countLiveNeighbors(cell, cells)));
20	}
21

